def recompute(fixture: dict[str, Any], records: list[dict[str, Any]]) -> dict[str, Any]:
    if not isinstance(fixture, dict) or set(fixture) != {"schema_version", "scope", "page_sets", "tasks"}:
        raise TagNavigationError("INVALID_BENCHMARK", "fixture 根字段非法")
    if fixture["schema_version"] != 1 or fixture["scope"] != "isolated-fixture":
        raise TagNavigationError("INVALID_BENCHMARK", "fixture schema/scope 非法")
    page_sets = fixture["page_sets"]
    if not isinstance(page_sets, dict) or set(page_sets) != set(CONDITIONS):
        raise TagNavigationError("INVALID_BENCHMARK", "page_sets 条件非法")
    normalized_sets = {condition: set(page_sets[condition]) for condition in CONDITIONS}
    if any(len(normalized_sets[c]) != len(page_sets[c]) for c in CONDITIONS):
        raise TagNavigationError("INVALID_BENCHMARK", "page_sets 含重复页面")
    task_map: dict[str, dict[str, Any]] = {}
    for task in fixture["tasks"]:
        if not isinstance(task, dict) or set(task) != {"task_id", "target", "accepted_routes"}:
            raise TagNavigationError("INVALID_BENCHMARK", "task 字段非法")
        if task["task_id"] in task_map or set(task["accepted_routes"]) != set(CONDITIONS):
            raise TagNavigationError("INVALID_BENCHMARK", "task ID 重复或条件非法")
        task_map[task["task_id"]] = task
    seen: set[tuple[str, str]] = set()
    rows: list[dict[str, Any]] = []
    for record in records:
        if not isinstance(record, dict) or set(record) != {
            "schema_version", "task_id", "condition", "visited_pages", "conflicting_tag_count"
        }:
            raise TagNavigationError("INVALID_BENCHMARK_RECORD", "record 字段非法")
        task_id = record["task_id"]
        condition = record["condition"]
        key = (task_id, condition)
        if record["schema_version"] != 1 or task_id not in task_map or condition not in CONDITIONS or key in seen:
            raise TagNavigationError("INVALID_BENCHMARK_RECORD", f"非法或重复记录 {key}")
        seen.add(key)
        visited = record["visited_pages"]
        if not isinstance(visited, list) or not visited or any(page not in normalized_sets[condition] for page in visited):
            raise TagNavigationError("INVALID_BENCHMARK_RECORD", f"{key} visited_pages 非法")
        task = task_map[task_id]
        if visited[-1] != task["target"]:
            raise TagNavigationError("INVALID_BENCHMARK_RECORD", f"{key} 未找到目标")
        route = task["accepted_routes"][condition]
        if not isinstance(route, list) or not route or route[-1] != task["target"]:
            raise TagNavigationError("INVALID_BENCHMARK", f"{key} accepted_route 非法")
        conflicts = record["conflicting_tag_count"]
        if not isinstance(conflicts, int) or isinstance(conflicts, bool) or conflicts < 0:
            raise TagNavigationError("INVALID_BENCHMARK_RECORD", f"{key} conflict 非法")
        rows.append(
            {
                "task_id": task_id,
                "condition": condition,
                "steps": len(visited) - 1,
                "misdirected_links": sum(1 for page in visited[:-1] if page not in route),
                "page_increment": 0,
                "conflicts": conflicts,
            }
        )
    expected = {(task_id, condition) for task_id in task_map for condition in CONDITIONS}
    if seen != expected:
        raise TagNavigationError("INCOMPLETE_BENCHMARK", f"missing={sorted(expected - seen)}")
    aggregate: dict[str, dict[str, Any]] = {}
    for condition in CONDITIONS:
        condition_rows = [row for row in rows if row["condition"] == condition]
        aggregate[condition] = {
            "tasks": len(condition_rows),
            "total_steps": sum(row["steps"] for row in condition_rows),
            "median_steps": median(row["steps"] for row in condition_rows),
            "misdirected_links": sum(row["misdirected_links"] for row in condition_rows),
            "page_count": len(normalized_sets[condition]),
            "conflicts": sum(row["conflicts"] for row in condition_rows),
        }
    page_increment = len(normalized_sets["confirmed_tag"] - normalized_sets["no_tag"])
    aggregate["confirmed_tag"]["page_increment"] = page_increment
    aggregate["no_tag"]["page_increment"] = 0
    rows.sort(key=lambda row: (row["task_id"], row["condition"]))
    return {
        "schema_version": 1,
        "status": "passed",
        "scope": "isolated-fixture",
        "effect_claim": "fixture-navigation-signal-only",
        "aggregate": aggregate,
        "records": rows,
    }

def build_projection(audit: dict[str, Any], policy: dict[str, Any]) -> dict[str, Any]:
    validate_policy(policy)
    if not isinstance(audit, dict) or audit.get("schema_version") != 1 or audit.get("status") != "passed":
        raise TagNavigationError("INVALID_AUDIT", "审计对象未通过")
    results = audit.get("results")
    if not isinstance(results, list):
        raise TagNavigationError("INVALID_AUDIT", "results 必须为数组")
    by_page: dict[str, list[dict[str, Any]]] = defaultdict(list)
    excluded_by_state: dict[str, int] = defaultdict(int)
    for result in results:
        if not isinstance(result, dict) or result.get("state") not in {"candidate", "confirmed", "contested", "deprecated"}:
            raise TagNavigationError("INVALID_AUDIT", "结果状态非法")
        if result["state"] == "confirmed":
            by_page[result["target"]["path"]].append(result)
        else:
            excluded_by_state[result["state"]] += 1
    entries: list[dict[str, Any]] = []
    suppressed: list[dict[str, Any]] = []
    limit = policy["max_tags_per_page"]
    for page in sorted(by_page):
        ranked = sorted(
            by_page[page],
            key=lambda result: (
                -result["metrics"]["support_votes"],
                result["metrics"]["opposition_ratio"],
                -result["metrics"]["independent_support_sources"],
                result["tag"],
            ),
        )
        selected = ranked[:limit]
        entries.append(
            {
                "page": page,
                "tags": [
                    {"tag": result["tag"], "display": f"#导航/{result['tag']}", "search": f"tag:#导航/{result['tag']}"}
                    for result in selected
                ],
            }
        )
        for result in ranked[limit:]:
            suppressed.append({"page": page, "tag": result["tag"], "reason_code": "PAGE_TAG_QUOTA_EXCEEDED"})
    return {
        "schema_version": 1,
        "status": "passed",
        "production_integration": "disabled",
        "page_tag_limit": limit,
        "entries": entries,
        "suppressed": suppressed,
        "excluded_by_state": {state: excluded_by_state.get(state, 0) for state in ("candidate", "contested", "deprecated")},
    }

def _replay(assertions: list[dict[str, Any]]) -> tuple[dict[tuple[str, str], list[dict[str, Any]]], set[str]]:
    by_id: dict[str, dict[str, Any]] = {}
    retracted: set[str] = set()
    grouped: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for assertion in assertions:
        if assertion["action"] == "retract":
            target_id = assertion["retracts"]
            target = by_id.get(target_id)
            if target is None or target["action"] == "retract":
                raise TagNavigationError("INVALID_RETRACTION", f"{assertion['assertion_id']} 指向不存在或非法事件")
            if target_id in retracted:
                raise TagNavigationError("INVALID_RETRACTION", f"{target_id} 已撤销")
            if _group_key(target) != _group_key(assertion) or target["actor"]["key"] != assertion["actor"]["key"]:
                raise TagNavigationError("INVALID_RETRACTION", f"{assertion['assertion_id']} 跨 actor/target/tag")
            retracted.add(target_id)
        by_id[assertion["assertion_id"]] = assertion
        grouped[_group_key(assertion)].append(assertion)
    return grouped, retracted

def _classify(
    events: list[dict[str, Any]],
    retracted: set[str],
    policy: dict[str, Any],
    current_commit: str,
    as_of: datetime,
) -> dict[str, Any]:
    active_proposals = [event for event in events if event["action"] == "propose" and event["assertion_id"] not in retracted]
    latest_votes: dict[str, dict[str, Any]] = {}
    vote_events = [event for event in events if event["action"] == "vote"]
    for event in vote_events:
        if event["assertion_id"] not in retracted:
            latest_votes[event["actor"]["key"]] = event
    active_votes = list(latest_votes.values())
    usable: list[dict[str, Any]] = []
    stale_count = 0
    drift_count = 0
    for vote in active_votes:
        observed = parse_timestamp(vote["evidence"]["observed_at"], "evidence.observed_at")
        age_seconds = (as_of - observed).total_seconds()
        if age_seconds < 0:
            raise TagNavigationError("FUTURE_EVIDENCE", vote["assertion_id"])
        stale = age_seconds > policy["max_evidence_age_days"] * 86400
        drift = vote["evidence"]["commit"] != current_commit
        stale_count += int(stale)
        drift_count += int(drift)
        if not stale and not drift:
            usable.append(vote)
    support = [vote for vote in usable if vote["stance"] == "support"]
    oppose = [vote for vote in usable if vote["stance"] == "oppose"]
    support_agents = {vote["actor"]["key"] for vote in support}
    support_sources = {vote["evidence"]["source_id"] for vote in support}
    denominator = len(support) + len(oppose)
    opposition_ratio = len(oppose) / denominator if denominator else 0.0
    reasons: list[str] = []
    if not active_votes:
        if active_proposals:
            state = "candidate"
            reasons.append("PROPOSAL_ONLY")
        else:
            state = "deprecated"
            if vote_events and all(event["assertion_id"] in retracted for event in vote_events):
                reasons.append("ALL_SUPPORT_RETRACTED")
            reasons.append("NO_ACTIVE_SUPPORT")
    elif not support:
        state = "deprecated"
        reasons.append("NO_ACTIVE_SUPPORT")
        if stale_count:
            reasons.append("STALE_EVIDENCE")
        if drift_count:
            reasons.append("COMMIT_DRIFT")
    elif opposition_ratio > policy["max_opposition_ratio"]:
        state = "contested"
        reasons.append("OPPOSITION_RATIO_EXCEEDED")
        if stale_count:
            reasons.append("STALE_EVIDENCE")
        if drift_count:
            reasons.append("COMMIT_DRIFT")
    else:
        if len(support) < policy["min_support_votes"]:
            reasons.append("SUPPORT_VOTES_BELOW_MINIMUM")
        if len(support_agents) < policy["min_independent_agents"]:
            reasons.append("INDEPENDENT_AGENTS_BELOW_MINIMUM")
        if len(support_sources) < policy["min_independent_sources"]:
            reasons.append("INDEPENDENT_SOURCES_BELOW_MINIMUM")
        if stale_count:
            reasons.append("STALE_EVIDENCE")
        if drift_count:
            reasons.append("COMMIT_DRIFT")
        if reasons:
            state = "candidate"
        else:
            state = "confirmed"
            reasons.append("CONFIRMED_THRESHOLDS_MET")
    return {
        "state": state,
        "reason_codes": sorted(set(reasons)),
        "metrics": {
            "proposal_count": len(active_proposals),
            "active_vote_count": len(active_votes),
            "support_votes": len(support),
            "oppose_votes": len(oppose),
            "independent_support_agents": len(support_agents),
            "independent_support_sources": len(support_sources),
            "opposition_ratio": round(opposition_ratio, 6),
            "stale_active_votes": stale_count,
            "drifted_active_votes": drift_count,
            "retracted_vote_count": sum(1 for event in vote_events if event["assertion_id"] in retracted),
            "superseded_vote_count": max(0, len([event for event in vote_events if event["assertion_id"] not in retracted]) - len(active_votes)),
        },
    }
